/* ============================================================================
 * ZeroDay Reapers × TheXSSRat — Offer Letter generator (portal drop-in)
 * Call generateOfferLetterHTML(student) on signup to build the letter, then
 * render it to PDF (see PORTAL-INTEGRATION.md) and email it to the student.
 * ==========================================================================*/

const OFFER_ASSETS = {
  zdr: "",
  rat: "",
  sig: ""
};

const OFFER_DEPT_CODES = {
  "Offensive Security": "OFF",
  "Defensive Security": "DEF",
  "Cloud Security": "CLD",
  "Governance, Risk & Compliance": "GRC",
  "Digital Forensics": "DF",
  "AI Security": "AI"
};

const OFFER_CSS = `
  :root{--bg:#070809;--ink:#eef2ee;--soft:#b7c0b8;--muted:#8a807f;--faint:#463b3b;--accent:#e01e2f;--accent-dim:rgba(224,30,47,.16);--line:rgba(238,242,238,.09);}
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{background:#101215;color:var(--ink);font-family:"JetBrains Mono",ui-monospace,Menlo,monospace;font-variant-numeric:slashed-zero;font-feature-settings:"zero" 1;}
  body{padding:26px 18px 60px;display:flex;flex-direction:column;align-items:center;gap:22px;}
  .panel{width:794px;max-width:100%;background:#15181c;border:1px solid #23282e;border-radius:10px;padding:18px 20px;}
  .panel h1{font-size:13px;letter-spacing:.28em;text-transform:uppercase;color:var(--accent);margin-bottom:4px;}
  .panel .hint{font-size:11px;color:#8a929a;margin-bottom:14px;line-height:1.6;}
  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;}
  .fld{display:flex;flex-direction:column;gap:5px;}.fld.wide{grid-column:span 3;}
  .fld label{font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:#8a929a;}
  .fld input,.fld select{background:#0d0f12;border:1px solid #2a3037;border-radius:6px;color:#eef2f5;padding:9px 11px;font-family:inherit;font-size:12.5px;}
  .fld input:focus,.fld select:focus{outline:none;border-color:var(--accent);}
  .actions{margin-top:14px;display:flex;gap:10px;align-items:center;}
  .btn{background:var(--accent);color:#fff;border:0;border-radius:6px;padding:11px 20px;font-family:inherit;font-size:12px;letter-spacing:.14em;text-transform:uppercase;cursor:pointer;font-weight:700;}
  .note{font-size:10.5px;color:#727b83;}
  .stage{filter:drop-shadow(0 24px 60px rgba(0,0,0,.6));}
  .doc{position:relative;width:794px;height:1123px;background:var(--bg);overflow:hidden;isolation:isolate;
    background-image:radial-gradient(120% 40% at 88% -4%,var(--accent-dim),transparent 55%),radial-gradient(80% 34% at 0% 104%,var(--accent-dim),transparent 60%);}
  .doc::before{content:"";position:absolute;inset:0;opacity:.45;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:30px 30px;-webkit-mask-image:radial-gradient(130% 80% at 50% 22%,#000 55%,transparent 92%);mask-image:radial-gradient(130% 80% at 50% 22%,#000 55%,transparent 92%);}
  .frame{position:absolute;inset:20px;border:1px solid var(--line);padding:34px 44px;display:flex;flex-direction:column;height:calc(100% - 40px);}
  .frame::before,.frame::after{content:"";position:absolute;width:18px;height:18px;border:1.5px solid var(--accent);}
  .frame::before{top:-1px;left:-1px;border-right:0;border-bottom:0;}.frame::after{bottom:-1px;right:-1px;border-left:0;border-top:0;}
  .cn{position:absolute;width:18px;height:18px;border:1.5px solid var(--accent);}.cn.tr{top:-1px;right:-1px;border-left:0;border-bottom:0;}.cn.bl{bottom:-1px;left:-1px;border-right:0;border-top:0;}
  .lhead{display:flex;justify-content:space-between;align-items:center;gap:16px;}
  .lhead .zdr{height:78px;width:auto;}
  .lhead .rat{height:58px;width:auto;}
  .htitle{flex:1;text-align:center;font-size:13px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--ink);line-height:1.55;}
  .htitle .x{color:var(--accent);margin:0 4px;}
  .htitle .sm{display:block;font-size:8.5px;letter-spacing:.34em;color:var(--muted);margin-top:5px;font-weight:400;}
  .hr{height:1px;background:linear-gradient(90deg,var(--accent),transparent);margin:16px 0 14px;}
  .meta1{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);letter-spacing:.06em;}
  .meta1 b{color:var(--ink);font-weight:500;}
  .eyebrow{margin-top:20px;font-size:10px;letter-spacing:.42em;color:var(--accent);text-transform:uppercase;}
  .eyebrow::before{content:"// ";color:var(--muted);}
  .subject{margin-top:8px;font-size:16px;font-weight:700;color:#fff;letter-spacing:.02em;}
  .dear{margin-top:16px;font-size:12px;color:var(--ink);}
  p.body{margin-top:11px;font-size:11px;line-height:1.85;color:var(--soft);letter-spacing:.01em;}
  p.body b{color:var(--ink);font-weight:500;} p.body .hi{color:var(--accent);}
  .details{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;margin-top:16px;border:1px solid var(--line);border-radius:6px;overflow:hidden;}
  .details div{padding:10px 14px;}
  .details div+div{border-left:1px solid var(--line);}
  .details .k{font-size:8px;letter-spacing:.24em;color:var(--muted);text-transform:uppercase;}
  .details .v{margin-top:5px;font-size:11.5px;color:var(--ink);}
  .terms{margin-top:14px;list-style:none;}
  .terms li{position:relative;padding-left:18px;font-size:10.5px;line-height:1.75;color:var(--soft);}
  .terms li::before{content:"\\25AA";position:absolute;left:0;color:var(--accent);}
  .terms li b{color:var(--ink);font-weight:500;}
  .sign-off{margin-top:auto;padding-top:16px;}
  .sign-off .rgds{font-size:11px;color:var(--soft);}
  .sign-off .sig{height:58px;width:auto;margin:4px 0 2px;}
  .sign-off .nm{font-size:12.5px;color:var(--ink);letter-spacing:.06em;}
  .sign-off .rl{font-size:8.5px;letter-spacing:.24em;color:var(--muted);text-transform:uppercase;margin-top:3px;}
  .lfoot{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:8px;letter-spacing:.16em;color:var(--muted);text-transform:uppercase;}
  .lfoot .g{color:var(--accent);}.lfoot a{color:var(--accent);text-decoration:none;}
  @media print{@page{size:A4 portrait;margin:0;}html,body{background:#000;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact;}.panel{display:none!important;}.stage{filter:none;}body{gap:0;}}
`;

function offerEsc(s){return (s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

// Build an ID like ZDR-2026-OFF-001. Prefer generating the sequence in the DB
// (see next_offer_id() in PORTAL-INTEGRATION.md) and pass it in as opts.id.
function makeOfferId(department, seq){
  const code = OFFER_DEPT_CODES[department] || "GEN";
  return "ZDR-2026-" + code + "-" + String(seq).padStart(3, "0");
}

function offerFormatDate(d){
  d = d || new Date();
  return d.toLocaleDateString("en-GB", { day:"2-digit", month:"long", year:"numeric" });
}

/**
 * generateOfferLetterHTML(student)
 * @param {Object} s
 *   s.fullName   {string}  candidate name
 *   s.department {string}  one of the 6 track names (keys of OFFER_DEPT_CODES)
 *   s.id         {string}  optional full ID (recommended: from DB next_offer_id)
 *   s.seq        {number}  optional sequence if you want makeOfferId() to build the ID
 *   s.issueDate  {string}  optional; defaults to today (the signup date)
 *   s.startDate  {string}  optional; defaults to "01 August 2026"
 * @returns {string} a complete, print-ready HTML document (A4 portrait)
 */
function generateOfferLetterHTML(s){
  const dept   = s.department || "Offensive Security";
  const id     = s.id || makeOfferId(dept, s.seq != null ? s.seq : 1);
  const issue  = s.issueDate || offerFormatDate(new Date());
  const start  = s.startDate || "01 August 2026";
  const name   = offerEsc(s.fullName) || "Candidate";
  const D      = offerEsc(dept);

  const letter = `<div class="frame"><span class="cn tr"></span><span class="cn bl"></span>
      <div class="lhead">
        <img class="zdr" src="data:image/png;base64,${OFFER_ASSETS.zdr}" alt="ZeroDay Reapers">
        <div class="htitle">ZeroDay Reapers <span class="x">×</span> TheXSSRat<span class="sm">Cybersecurity Internship</span></div>
        <img class="rat" src="data:image/png;base64,${OFFER_ASSETS.rat}" alt="TheXSSRat">
      </div>
      <div class="hr"></div>
      <div class="meta1"><span>ID: <b>${offerEsc(id)}</b></span><span>Date: <b>${offerEsc(issue)}</b></span></div>
      <div class="eyebrow">internship_offer</div>
      <div class="subject">Internship Offer — ${D} Track</div>
      <div class="dear">Dear <b>${name}</b>,</div>
      <p class="body">Congratulations! On behalf of <b>ZeroDay Reapers</b>, we are delighted to offer you a place in our <b>6-Week Hands-On Cybersecurity Internship</b>, in the <span class="hi">${D}</span> track. This program is proudly run in collaboration with <b>TheXSSRat</b>.</p>
      <p class="body">This is a <b>remote, project-based</b> internship built entirely around real-world, practical missions — one each week for six weeks. Your tasks are matched to your hardware, you'll collaborate with a team of fellow interns, and you'll be mentored throughout via our private community.</p>
      <div class="details">
        <div><div class="k">Track</div><div class="v">${D}</div></div>
        <div><div class="k">Duration</div><div class="v">6 Weeks · 6 Tasks</div></div>
        <div><div class="k">Start Date</div><div class="v">${offerEsc(start)}</div></div>
        <div><div class="k">Mode</div><div class="v">Remote</div></div></div>
      <ul class="terms"><li>Top performers earn <b>exclusive resources from TheXSSRat</b> and a <b>Letter of Recommendation</b> for the very best.</li></ul>
      <p class="body">We're thrilled to have you on board and can't wait to see what you build. Welcome to the team.</p>
      <div class="sign-off"><div class="rgds">Warm regards,</div>
        <img class="sig" src="data:image/png;base64,${OFFER_ASSETS.sig}" alt="Signature">
        <div class="nm">Ali Raza</div><div class="rl">Founder &amp; CEO · ZeroDay Reapers</div></div>
      <div class="lfoot"><span><span class="g">●</span> This is an official ZeroDay Reapers internship offer</span><a href="https://zerodayreapers.me">zerodayreapers.me</a></div>
    </div>`;

  return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">
<style>${OFFER_CSS}
  body{padding:0;margin:0;background:#000;display:block}
  .stage{filter:none} .doc{margin:0}
</style></head>
<body><div class="doc">${letter}</div></body></html>`;
}

// For bundlers / modules:
if (typeof module !== "undefined" && module.exports) {
  module.exports = { generateOfferLetterHTML, makeOfferId, offerFormatDate, OFFER_DEPT_CODES };
}

export { generateOfferLetterHTML, makeOfferId, offerFormatDate, OFFER_DEPT_CODES };
